    if text_after.count('\n') > 2:
        category = "multi-line"
    elif '\\n' in text_after:
        category = "escaped_newline" 
    else:
        category = "single-line"

    key = category
    if key not in patterns_after:
        patterns_after[key] = []
    if len(patterns_after[key]) < 3:
        patterns_after[key].append((m.start(), start, end, text_after[:300]))

